          ruleId: "MSG-QUEUE-POLICY-OPEN",
          severity: "high",
          title: "Queue policy allows any principal without a condition",
          explanation: "Anyone could send to or read from the queue.",
          subject: at(p.logicalId),
          resources: [at(p.logicalId)],
