// src/lib/tools.ts
var isObject2 = (v) => typeof v === "object" && v !== null && !Array.isArray(v);
function attributesToValues(attributes) {
  if (!isObject2(attributes)) return { ok: false, error: "message attributes must be an object" };
  const out = {};
  for (const [name, raw] of Object.entries(attributes)) {
    if (!isObject2(raw) || typeof raw["Type"] !== "string" || raw["Value"] === void 0)
      return { ok: false, error: `attribute ${name} needs Type and Value` };
    const type = raw["Type"];
    const value = raw["Value"];
    if (type === "Number") {
      const n = Number(value);
      if (!Number.isFinite(n)) return { ok: false, error: `attribute ${name} is not a number` };
      out[name] = n;
    } else if (type === "String.Array") {
      try {
        const parsed = typeof value === "string" ? JSON.parse(value) : value;
        if (!Array.isArray(parsed)) throw new Error("not a list");
        out[name] = parsed;
      } catch {
        return { ok: false, error: `attribute ${name} is not a JSON list` };
      }
    } else out[name] = value;
  }
  return { ok: true, value: out };
}
var ALLOWED = /^[A-Za-z0-9!"#$%&'()*+,\-./:;<=>?@[\\\]^_`{|}~]+$/;
function checkFifoSend(input) {
  const problems = [];
  if (input.groupId === void 0 || input.groupId === "")
    problems.push("MessageGroupId is required for every message sent to a FIFO queue.");
  else if (input.groupId.length > 128 || !ALLOWED.test(input.groupId))
    problems.push("MessageGroupId must be 1 to 128 characters: letters, digits, and punctuation.");
  if (!input.contentBased && (input.dedupId === void 0 || input.dedupId === ""))
    problems.push("MessageDeduplicationId is required because content-based deduplication is off.");
  if (input.dedupId !== void 0 && input.dedupId !== "" && !ALLOWED.test(input.dedupId))
    problems.push(
      "MessageDeduplicationId uses characters outside letters, digits, and punctuation."
    );
  return problems;
}
function diagnoseBacklog(i) {
  const out = [];
  if (i.sendRatePerSec > i.receiveRatePerSec)
    out.push({
      statement: "Messages arrive faster than they are consumed, so the backlog grows.",
      basis: `send ${i.sendRatePerSec}/s > receive ${i.receiveRatePerSec}/s`,
      next: "Check consumer concurrency, batch size, and consumer errors; for Lambda check throttles and the event source mapping's maximum concurrency."
    });
  if (i.inFlight > 0 && i.visible > 0 && i.receiveRatePerSec === 0)
    out.push({
      statement: "Consumers hold messages but finish none: they may be stuck or failing after receive.",
      basis: `${i.inFlight} in flight, nothing received per second`,
      next: "Look at consumer errors and timeouts; compare processing time with the visibility timeout."
    });
  if (i.oldestAgeSeconds > i.retentionSeconds * 0.8)
    out.push({
      statement: "The oldest message is close to the retention limit and may expire unprocessed.",
      basis: `oldest ${i.oldestAgeSeconds}s of ${i.retentionSeconds}s retention`,
      next: "Raise retention temporarily and add consumer capacity, or move old messages to a dead-letter queue deliberately."
    });
  if (i.oldestAgeSeconds > i.visibilitySeconds * 3 && i.dlqDepth === 0 && i.visible > 0)
    out.push({
      statement: "Old messages are being retried but never dead-lettered: a poison message may loop, or no redrive policy exists.",
      basis: `oldest ${i.oldestAgeSeconds}s, dead-letter depth 0`,
      next: "Check that a redrive policy exists and what maxReceiveCount is; read one message's receive count (that is a receive, so do it deliberately)."
    });
  if (i.dlqDepth > 0)
    out.push({
      statement: "Messages are failing permanently and landing in the dead-letter queue.",
      basis: `${i.dlqDepth} message(s) in the dead-letter queue`,
      next: "Sample a few dead-lettered messages with the owner's approval, find the shared cause, fix the consumer, then redrive in a controlled batch."
    });
  if (out.length === 0)
    out.push({
      statement: "Nothing in these numbers points to a problem.",
      basis: "all checks passed",
      next: "A small backlog under steady load can be normal; compare with the usual baseline."
    });
  return out;
}

// src/lib/cli.ts
var runCli = defineCli({
  name: "aws-messaging",
  promise: "Reads files inside the project. Writes nothing. No AWS calls: it sends, receives, deletes, or redrives no messages.",
  valued: [
    "scope",
    "group",
    "dedup",
    "visible",
    "in-flight",
    "oldest",
    "receive-rate",
    "send-rate",
    "visibility",
    "retention",
    "dlq"
  ],
  flags: ["content-based"],
  commands: {
    inspect: {
      help: "[path]  Queues, topics, and subscriptions in cdk.out, with findings",
      run: (ctx) => {
        const { stacks, problems } = ctx.stacks(ctx.words[0]);
        if (stacks.length === 0) return noTemplates(ctx, problems, ctx.words[0]);
        const rows = eachStack(stacks, (s) => inventory(s.name, s.template));
        const findings = eachStack(stacks, (s) => rules(s.name, s.template));
        const report = localReport(
          "aws-messaging",
          `${rows.length} queue/topic/subscription resource(s) in ${stacks.length} stack(s), ${findings.length} finding(s). Source: synthesized templates (declared).`,
          findings,
          [
            TEMPLATE_LIMITATION,
            "Queue depth, message age, and receive counts are run-time facts that a template cannot show; use `diagnose` with numbers you read."
          ],
          ctx.now
        );
        return reportResult(ctx, report, [
          `Resources:
${rows.map((r) => `  ${r.kind.padEnd(13)} ${r.id}  ${r.detail}`).join("\n")}`,
          ...problems
        ]);
      }
    },
    "filter-test": {
      help: "<policy.json> <message.json> [--scope attributes|body]  Does an SNS filter policy accept the message?",
      run: (ctx) => {
        const [p, m] = ctx.words;
        if (p === void 0 || m === void 0)
          return ctx.fail("filter-test needs a policy file and a message file", 2);
        const scope = ctx.args.one("scope") ?? "attributes";
        if (scope !== "attributes" && scope !== "body")
          return ctx.fail("--scope must be attributes or body", 2);
        const policy = ctx.readJson(p, MAX_PATTERN_BYTES);
        const message = ctx.readJson(m, 1e6);
        if (!policy.ok) return ctx.fail(policy.error);
        if (!message.ok) return ctx.fail(message.error);
        const problems = checkPattern(policy.value);
        if (problems.length > 0)
          return ctx.fail(
            `The policy is not valid:
${problems.map((x) => `  ${x.path}: ${x.message}`).join("\n")}`
          );
        let subject;
        if (scope === "attributes") {
          const converted = attributesToValues(message.value);
          if (!converted.ok) return ctx.fail(converted.error);
          subject = converted.value;
        } else subject = message.value;
        const pattern = policy.value;
        const ok = matches(pattern, subject);
        const why = ok ? [] : explainMiss(pattern, subject);
        return ctx.out(
          { matches: ok, scope, why },
          ok ? `DELIVERED: the ${scope} satisfy the filter policy.
(Checked locally with EventBridge-style operators; SNS supports a similar but not identical set. SNS is the authority.)` : `FILTERED OUT:
${why.map((x) => `  ${x}`).join("\n")}
(Checked locally; SNS is the authority.)`
        );
      }
    },
    "fifo-check": {
      help: "--group <id> [--dedup <id>] [--content-based]  What a send to a FIFO queue needs",
      run: (ctx) => {
        const problems = checkFifoSend({
          ...ctx.args.one("group") === void 0 ? {} : { groupId: ctx.args.one("group") },
          ...ctx.args.one("dedup") === void 0 ? {} : { dedupId: ctx.args.one("dedup") },
          contentBased: ctx.args.flags.has("content-based")
        });
        const note = "Ordering holds within one message group id. Many groups give parallelism; a single group id serializes everything. FIFO queues limit each partition to 300 transactions per second per API action (3,000 messages with batching) unless high throughput mode is on.";
        return ctx.out(
          { ok: problems.length === 0, problems },
          problems.length === 0 ? `The send is valid for a FIFO queue.
${note}` : `${problems.map((p) => `- ${p}`).join("\n")}
${note}`
        );
      }
    },
    diagnose: {
      help: "--visible n --in-flight n --oldest s --send-rate n --receive-rate n --visibility s --retention s --dlq n  Hypotheses from numbers you read",
      run: (ctx) => {
        const get = (n) => ctx.args.num(n, Number.NaN);
        const input = {
          visible: get("visible"),
          inFlight: get("in-flight"),
          oldestAgeSeconds: get("oldest"),
          receiveRatePerSec: get("receive-rate"),
          sendRatePerSec: get("send-rate"),
          visibilitySeconds: get("visibility"),
          retentionSeconds: get("retention"),
          dlqDepth: get("dlq")
        };
        if (Object.values(input).some((v) => !Number.isFinite(v) || v < 0))
          return ctx.fail(
            "diagnose needs every number: --visible --in-flight --oldest --send-rate --receive-rate --visibility --retention --dlq (non-negative). Read them from CloudWatch; this command does not.",
            2
          );
        const hyp = diagnoseBacklog(input);
        return ctx.out(
          hyp,
          `Hypotheses (from the numbers you gave, not from the queue):
${hyp.map((h, i) => `${i + 1}. ${h.statement}
   Basis: ${h.basis}
   Check next: ${h.next}`).join("\n")}`
        );
      }
    }
  }
});

